# 13.11: «вариантов мало, роботизированно, возьми мою стилистику и правила»; на отзыв о «Ярцевой Нине Дмитриевне» ответа не было вовсе
# (проверка имён не узнала «Нине» по «Нины»). Проверяем на 8 отзывах в духе реальных (выдуманные тексты):
# ответ есть всегда; подробный отзыв — развёрнутый ответ; благодарность — с пожеланием в конце; на странице больницы — «передадим» названным
# людям и медсёстрам одной фразой; на странице врача — без «передадим» и без больницы; запрещённых фраз нет
import asyncio, sys, json, re
from playwright.async_api import async_playwright
P = "file://" + sys.argv[1]
ST = [["Ярцева Нина Дмитриевна", "врач-колопроктолог", "Колопроктологическое отделение 3"], ["Корнев Леонид Владимирович", "заведующий отделением - врач-колопроктолог", "Колопроктологическое отделение 3"],
      ["Шалаева Татьяна Ильинична", "врач-хирург", "Консультативно-диагностическое отделение"], ["Рябов Сергей Андреевич", "врач-невролог", "Неврологическое отделение"]]
R = [
 ["ПроДокторов", "Страница больницы", "Мне посчастливилось попасть в руки профессионала - Корнева Леонида Владимировича и его ассистента и лечащего врача Ярцевой Нины Дмитриевны. От всего сердца хочу выразить вам огромную благодарность за ваш профессионализм! Медперсонал приветливый, удобные палаты, меню вкусное, чисто и комфортно. Операция была непростая, всё прошло хорошо.", 5, "Наталья"],
 ["ПроДокторов", "Страница больницы", "Записалась к врачу Шалаевой Татьяне Ильиничне и не пожалела. Врач очень внимательный и компетентный. Обследовалась быстро. Прооперировалась и выписалась на следующий день. Всегда была под наблюдением врача. Выражаю большую благодарность хирургу Татьяне Ильиничне. Здоровья ей и сил. Спасибо медсестрам и всему персоналу.", 5, ""],
 ["ДокТу", "Карточка врача: Рябов С.А.", "Рябов Сергей Андреевич — хороший врач и просто замечательный человек. Он профессионал в своей области, и это чувствуется. Никогда не игнорирует пациентов, всегда помнит о нас. Если встречает меня в коридоре, обязательно интересуется, как я себя чувствую. Это приятно и важно.", None, ""],
 ["Яндекс", "ГКБ 24", "Отличная клиника, рекомендую!!!", 5, "Дмитрий"],
 ["Яндекс", "ГКБ 24", "Моя бабушка по скорой поступила в кардиореанимацию. Доктор был со мной на связи всё время, выслушал все опасения. Потом нас перевели в кардиологию, где лечащий врач быстро разобралась в проблеме. Мы с бабушкой выражаем огромную благодарность этим замечательным специалистам и желаем им крепкого здоровья.", 5, "Анастасия"],
 ["ПроДокторов", "Карточка врача: Рябов С.А.", "Попала по скорой с острой болью, доктор провёл экстренную помощь, мне было очень страшно, но всё прошло хорошо. Спасибо вам большое!", 5, "Ольга"],
 ["ПроДокторов", "Страница больницы", "Обратилась по плановой госпитализации в гинекологию. Очень понравилось отношение врачей. Нет ощущения больницы, будто в санатории. Хорошее настроение и лёгкие разговоры заставили забыть, что у меня операция. Отельный уровень палат и питания.", 5, ""],
 ["ПроДокторов", "Карточка врача: Рябов С.А.", "У меня есть ДМС. В страховой компании мне настоятельно рекомендовали выбрать больницу №24. Я сильно переживала, так как у меня ничего не болело. Но доктор меня успокоил, всё подробно объяснил. За несколько дней до операции доктор прислал мне рекомендации по подготовке и питанию. Я не волновалась даже. Операция прошла благополучно. Доктор приходил ко мне в палату несколько раз в день. Я очень ему благодарна за профессионализм и эмпатию. Также отмечу весь медперсонал отделения, они относятся к пациентам с теплом и заботой. Отдельно подчеркну вкусное и разнообразное питание.", None, ""],
 ["ДокТу", "Карточка врача: Рябов С.А.", "Сергей Андреевич настоящий профессионал! Внимательно выслушал, подробно объяснил всё, что меня волновало, его чувство юмора помогло мне расслабиться. Я осталась довольна его работой!", None, ""],
]
BAN = re.compile(r"надёжных руках|ради чего мы работаем|лучшая поддержка|радостно читать|становиться лучше|особенно ценим|гордимся|сожале|извин|клиник|понятен каждый шаг|не заканчивается после операции", re.I)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); pg = await b.new_page(); errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto(P); await pg.wait_for_timeout(2500)
        out = await pg.evaluate("""async ([R, ST]) => { const refs = Object.assign({}, window.__otvReports.refs() || {}); refs.staff = ST; window.__otvReports._setRefs(refs);
          const res = []; for (const [pl, page, text, rating, author] of R) { const it = { platform: pl, page, review: text, rating, author }; const vs = [];
            const a = window.__otvGen.answer(it); if (a) vs.push(a.text);
            for (let i = 0; i < 6; i++) { try { vs.push(await window.__otvVariant({ kind: 'answer', platform: pl, page, review: text, author, rating })); } catch (e) { vs.push(''); } }
            res.push({ page, len: text.length, vs }); } return res; }""", [R, ST])
        res = []
        body = lambda v: re.sub(r'^Здравствуйте[^\n]*\n', '', v).replace('С уважением, администрация 24 Московской больницы', '').strip()
        nsent = lambda v: len([x for x in re.split(r'(?<=[.!?])\s+', body(v)) if x.strip()])
        empty = [i for i, r in enumerate(out) if not r['vs'][0]]
        res.append((not empty, 'ответ есть на каждый отзыв (в том числе о «Ярцевой Нине Дмитриевне»)', empty))
        few = [i for i, r in enumerate(out) if len(set(v for v in r['vs'] if v)) < 4]
        res.append((not few, 'на каждый отзыв — не меньше 4 разных вариантов', few))
        short = [(i, nsent(v)) for i, r in enumerate(out) if r['len'] > 300 for v in r['vs'][:3] if v and nsent(v) < 4]
        res.append((not short, 'подробный отзыв — развёрнутый ответ (4 фразы и больше)', short[:4]))
        wish = [i for i, r in enumerate(out) if r['len'] > 250 and not re.search(r'Желаем здоровья', r['vs'][0])]
        res.append((not wish, 'подробная благодарность — с «Желаем здоровья…» в конце', wish))
        bad = [(i, BAN.search(v).group(0)) for i, r in enumerate(out) for v in r['vs'] if v and BAN.search(v)]
        res.append((not bad, 'нет запрещённых и роботизированных фраз', bad[:5]))
        doc = [v for r in out if 'врача' in r['page'] for v in r['vs'] if v and re.search(r'передад|больниц|стационар|наш\S* сотрудник', body(v), re.I)]
        res.append((not doc, 'страница врача: без «передадим» и без больницы', doc[:2]))
        h1 = out[1]['vs'][0]
        res.append(('Татьяне Ильиничне' in h1 and 'сёстрам' in h1 and h1.count('передад') + h1.count('Передад') <= 1, 'страница больницы: «передадим» Татьяне Ильиничне и медсёстрам одной фразой', h1))
        h0 = out[0]['vs'][0]
        res.append(('Нине Дмитриевне' in h0 and 'Леониду Владимировичу' in h0, 'оба врача из отзыва — в фразе «передадим»', h0))
        fam = out[4]['vs'][0]
        res.append(('близким' in fam, 'в отзыве семья — «Желаем здоровья вам и вашим близким»', fam))
        first = [v for r in out for v in r['vs'] if v and not re.match(r'(Спасибо|Благодарим|Приятно|Важно и приятно|Рады|Очень рады)', body(v))]
        res.append((not first, 'ответ начинается с благодарности, а не с «Передадим…»', first[:2]))
        # 13.11: «мне рекомендации» читалось как «не рекомендую» — восторженный отзыв получал ответ как на жалобу
        dms = out[7]['vs'][0]
        res.append(('gkb24@' not in dms and 'Желаем здоровья' in dms and len([x for x in re.split(r'(?<=[.!?])\s+', body(dms)) if x.strip()]) >= 4, '«мне рекомендации» — не «не рекомендую»: ответ как на благодарность, развёрнутый', dms))
        res.append((not errs, 'без ошибок страницы', errs[:3]))
        ok = True
        for good, name, info in res: print(('OK   ' if good else 'FAIL ') + name + ('' if good else '  ' + json.dumps(info, ensure_ascii=False)[:700])); ok = ok and good
        print('ALL OK' if ok else 'FAILED'); await b.close(); sys.exit(0 if ok else 1)
asyncio.run(main())
